<?php

declare(strict_types=1);

namespace Inventory\Shared\Domain;

use Inventory\Shared\Domain\Exception\InvalidValue;
use Stringable;
use Symfony\Component\Uid\Uuid;

/** UUIDv7, generated by the application, so an entity has an identity before it is persisted. */
abstract readonly class Identifier implements Stringable
{
    final protected function __construct(public string $value)
    {
    }

    public static function generate(): static
    {
        return new static(Uuid::v7()->toRfc4122());
    }

    public static function fromString(string $value): static
    {
        if (!Uuid::isValid($value)) {
            throw new InvalidValue('id', "'{$value}' is not a valid identifier.");
        }

        return new static(strtolower($value));
    }

    public function equals(self $other): bool
    {
        return $other::class === static::class && $other->value === $this->value;
    }

    public function __toString(): string
    {
        return $this->value;
    }
}
